var isVisible = false;

function OnToggleStatsUIPressed() {
    // $.Msg("[STATS] Toggle key pressed");

    isVisible = !isVisible;
    statsPanel.visible = isVisible;

    if (isVisible) {
        // $.Msg("[STATS] Request stats from server");
        GameEvents.SendCustomGameEventToServer("request_stats", {});
