(function () {

    statsPanel = $("#StatsPanel");
    statsColumns = $("#StatsColumns");

    statsPanel.visible = false;

    GameEvents.Subscribe("update_stats", function (data) {
        UpdateStatsUI(data.final, data.breakdown);
    });

    const ITEMS_PER_COLUMN = 12;

    function UpdateStatsUI(finalStats, breakdown) {
        statsColumns.RemoveAndDeleteChildren();

        let keys = Object.keys(finalStats);
        let col = null;
        let count = 0;

        keys.forEach((key) => {

            if (count % ITEMS_PER_COLUMN === 0) {
                col = $.CreatePanel("Panel", statsColumns, "");
                col.AddClass("stat-column");
            }

            // 主属性
            let main = $.CreatePanel("Label", col, "");
            main.AddClass("stat-line");
            main.text = key + "：" + finalStats[key];

            // breakdown（必须是数组）
            let list = breakdown[key];
            if (list && Array.isArray(list)) {
                list.forEach(function (entry) {
                    let b = $.CreatePanel("Label", col, "");
                    b.AddClass("breakdown-line");
                    b.text = entry.source + "：+" + entry.value;
                });
            }

            count++;
        });
    }

})();

