    GameEvents.Subscribe("update_stats", function (data) {
        UpdateStatsUI(data.final, data.breakdown);
    });

    const ITEMS_PER_COLUMN = 12;

    function UpdateStatsUI(finalStats, breakdown) {
        statsColumns.RemoveAndDeleteChildren();

        let keys = Object.keys(finalStats);
        let col = null;
        let count = 0;

        keys.forEach((key) => {

